"""Every rounding rule of meterbill lives here (see docs/rounding.md).

The decimal functions work on exact integers and build their results from
digit tuples, so they do not depend on any process state.
"""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


# --- helpers -----------------------------------------------------------------


def _check_method(method) -> None:
    if not isinstance(method, str) or method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")


def _check_step(step) -> None:
    if not isinstance(step, Decimal):
        raise TypeError("step must be a Decimal")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")


def _check_value(value) -> None:
    if not isinstance(value, Decimal):
        raise TypeError("value must be a Decimal")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _int_exp(d: Decimal) -> tuple:
    """(signed coefficient, exponent) of a finite Decimal; the sign of zero is dropped."""
    sign, digits, exp = d.as_tuple()
    coef = int("".join(map(str, digits)))
    return (-coef if sign else coef), exp


def _fraction(d: Decimal) -> Fraction:
    coef, exp = _int_exp(d)
    return Fraction(coef) * Fraction(10) ** exp


def _cut(ratio: Fraction, method: str) -> int:
    """The magnitude of `ratio` as a whole number, rounded by `method`."""
    ratio = abs(ratio)
    q, r = divmod(ratio.numerator, ratio.denominator)
    if method == DOWN:
        return q
    twice = 2 * r
    if twice > ratio.denominator:
        return q + 1
    if twice < ratio.denominator:
        return q
    if method == HALF_UP:
        return q + 1
    return q + (q % 2)


def _decimal(units: int, negative: bool, step: Decimal) -> Decimal:
    """`units` steps as a Decimal that carries the exponent of `step`."""
    coef, exp = _int_exp(step)
    digits = tuple(int(c) for c in str(units * coef))
    return Decimal((1 if negative else 0, digits, exp))


# --- public ------------------------------------------------------------------


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` decides ties and direction."""
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    _check_method(method)
    _check_step(step)
    _check_value(value)
    units = _cut(_fraction(value) / _fraction(step), method)
    return _decimal(units, value.is_signed(), step)


def _bit(x: tuple) -> bool:
    """The sign of a (value, sign of zero) pair."""
    return x[0] < 0 if x[0] != 0 else x[1]


def _add(a: tuple, b: tuple) -> tuple:
    """Decimal addition of two (value, sign of zero) pairs: a zero sum is negative only if both are."""
    total = a[0] + b[0]
    return total, (_bit(a) and _bit(b)) if total == 0 else False


def _neg(a: tuple) -> tuple:
    return -a[0], not a[1]


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """One part per amount, each a multiple of `step`, adding up to the rounded sum.

    Every amount is cut toward zero to the step; what the cuts lost against
    the sum rounded half up goes on the last amount that is not zero.
    """
    amounts = list(amounts)
    if not isinstance(step, Decimal):
        raise TypeError("step must be a Decimal")
    _check_step(step)
    for a in amounts:
        _check_value(a)
    if not amounts:
        return []
    unit = _fraction(step)
    ratios = [_fraction(a) / unit for a in amounts]
    signs = [a.is_signed() for a in amounts]

    parts = []
    for ratio, neg in zip(ratios, signs):
        units = _cut(ratio, DOWN)
        parts.append((-units if ratio < 0 else units, neg))

    exact = (Fraction(0), False)
    for ratio, neg in zip(ratios, signs):
        exact = _add(exact, (ratio, neg))
    whole_units = _cut(exact[0], HALF_UP)
    whole = (-whole_units if exact[0] < 0 else whole_units, _bit(exact))

    cut = (0, False)
    for p in parts:
        cut = _add(cut, p)
    rest = _add(whole, _neg(cut))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] = _add(parts[i], rest)
            break
    return [_decimal(abs(v), _bit((v, z)), step) for v, z in parts]


def legacy_cents(value: float, places: int = 2) -> float:
    """A float amount settled the way the old customer system settled it.

    Binary floating point on purpose: scale, add a half, floor, scale back.
    """
    if isinstance(places, bool) or not isinstance(places, int):
        raise TypeError("places must be an int")
    if not 0 <= places <= 6:
        raise ValueError("places must be between 0 and 6")
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` written with `places` digits after the point."""
    if isinstance(places, bool) or not isinstance(places, int):
        raise TypeError("places must be an int")
    if places < 0:
        raise ValueError("places must not be negative")
    if isinstance(value, Decimal):
        _check_method(method)
        _check_value(value)
        step = Decimal((0, (1,), -places))
        units = _cut(_fraction(value) / _fraction(step), method)
        text = str(units).rjust(places + 1, "0")
        if places:
            text = text[:-places] + "." + text[-places:]
        return ("-" if value.is_signed() else "") + text
    if isinstance(value, float):
        _check_method(method)
        if method != HALF_EVEN:
            raise ValueError("a float is only written half to even")
        return format(value, f".{places}f")
    raise TypeError("value must be a float or a Decimal")

"""Value added tax on a bill's subtotal."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money


def vat(subtotal: Decimal, rate: Decimal) -> Decimal:
    # Tax offices settle half to even; this is the one amount that does not go half up.
    return money.round_amount(subtotal * rate, money.CENT, money.HALF_EVEN)


def rate_label(rate: Decimal) -> str:
    """`VAT 21%`; a rate with a fraction of a percent is shown to the nearest percent."""
    return f"VAT {money.fixed(rate * 100, 0, money.HALF_UP)}%"

"""Credits from the old customer system, which stores them as binary floats."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money


def settle(amount: float) -> float:
    """A credit as the old system settled it, to the cent."""
    return money.legacy_cents(amount)


def total(credits) -> Decimal:
    s = 0.0
    for c in credits:
        s += settle(c.amount)
    return Decimal(money.fixed(s, 2))


def line(credit) -> str:
    return money.fixed(settle(credit.amount), 2)

"""The standing charge: a daily rate over one or more date segments."""

from __future__ import annotations

from decimal import Decimal

from meterbill import money
from meterbill.model import Account, Segment


def segments_for(account: Account, rate: Decimal) -> list:
    """The account's own segments, or one segment over the whole period at `rate`."""
    if account.standing:
        return list(account.standing)
    return [Segment(account.start, account.end, rate)]


def prorate(segments: list) -> list:
    """One charge per segment, in cents, adding up to the rounded charge of the whole.

    Each segment is cut down to the cent; what the cuts lost against the
    rounded total goes on the last segment that has a charge.
    """
    return money.allocate([Decimal(s.days) * s.rate for s in segments], money.CENT)

import json, os, random, subprocess, sys, tempfile, shutil
from concurrent.futures import ThreadPoolExecutor
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 1)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 150

def run(root, *args):
    env = {**os.environ, "PYTHONDONTWRITEBYTECODE": "1"}
    r = subprocess.run([sys.executable, "-m", "meterbill", *args], cwd=root, env=env, capture_output=True, text=True)
    return r.returncode, r.stdout, r.stderr

def price():
    return random.choice(["0.2140", "0.25", "0.125", "0.0125", "0.2005", "0.15", "0.3", "0.0625", "0.5", "1.8450", "0.001", "0.2462", "0"])

def book():
    cur = {"EUR": {"cash": random.choice(["none", "whole", "0.05", "0.1", "0.5", "1", "0.25", "0.010", "5", "0.001"])},
           "CHF": {"cash": random.choice(["0.05", "whole", "none", "0.10"])}}
    t = {}
    for i in range(3):
        nb = random.randint(1, 3)
        ups = sorted(random.sample([10, 50, 100, 150, 300, 1000], nb - 1))
        bands = [{"upto": str(u), "price": price()} for u in ups] + [{"upto": None, "price": price()}]
        t[f"t{i}"] = {"currency": random.choice(list(cur)), "vat": random.choice(["0.21", "0.081", "0.125", "0.075", "0.0625", "0", "0.195", "0.005", "0.1"]),
                      "standing": random.choice(["0.4110", "0.5", "0.125", "0.0005", "0", "4.10", "0.3333"]), "bands": bands}
    return {"currencies": cur, "tariffs": t}

def kwh():
    return random.choice([str(random.randint(0, 600)), f"{random.randint(0,6000)/10}", f"{random.randint(0,60000)/100}", "0", f"{random.randint(0,600)}.5", "0.5", "8", "2.5", f"{random.randint(1,999)}.125"])

def account(i, tnames):
    s = random.randint(1, 20); e = s + random.randint(0, 40)
    d = lambda x: f"2026-{1 + (x - 1)//28:02d}-{(x - 1) % 28 + 1:02d}"
    a = {"account": f"A-{i}", "name": "n", "tariff": random.choice(tnames), "period": {"start": d(s), "end": d(e)},
         "readings": [{"meter": "M", "kwh": kwh()} for _ in range(random.randint(0, 3))]}
    if random.random() < .6:
        cuts = sorted(random.sample(range(s, e + 1), min(2, e - s + 1)))
        segs = []
        pos = s
        for c in cuts + [e]:
            if c < pos: continue
            segs.append({"from": d(pos), "to": d(c), "rate": random.choice(["0.4113", "0.4387", "-0.0003", "0", "0.0050", "0.125", "-0.4", "0.0049"]),})
            pos = c + 1
        a["standing"] = segs
    a["credits"] = [{"ref": f"C{j}", "amount": random.choice([-4.25, 4.256, 1.005, 2.675, 0.125, -0.005, -0.004, 0.1, -1.1, 0.3, 1e-9, -1e-9, 3, 1234567.891, 0.004999999, 2.5e-3, -0.0, 7.0049999999999999])}
                    for j in range(random.randint(0, 3))]
    return a

def case(k):
    d = tempfile.mkdtemp()
    b = book()
    bp = os.path.join(d, "book.json")
    json.dump(b, open(bp, "w"))
    names = sorted(b["tariffs"])
    accs = os.path.join(d, "accs"); os.mkdir(accs)
    paths = []
    for i in range(random.randint(1, 5)):
        p = os.path.join(accs, f"a{i}.json"); json.dump(account(1000 + i, names), open(p, "w")); paths.append(p)
    cmds = [["--tariffs", bp, "tariffs"]]
    for p in paths:
        for f in ("text", "csv", "json"):
            cmds.append(["--tariffs", bp, "bill", p, "--format", f])
    for f in ("text", "csv"):
        cmds.append(["--tariffs", bp, "batch", accs, "--format", f, "--workers", str(random.randint(1, 4))])
    for _ in range(3):
        for f in ("text", "json"):
            cmds.append(["--tariffs", bp, "quote", random.choice(names), kwh(), str(random.randint(1, 90)), "--format", f])
    bad = []
    for c in cmds:
        o = run("/tmp/orig", *c); n = run("/app", *c)
        if o != n:
            bad.append((c, o, n))
    shutil.copytree(d, f"/tmp/cases_{k}") if bad else shutil.rmtree(d)
    return k, len(cmds), bad

tot = 0; allbad = []
with ThreadPoolExecutor(8) as ex:
    for k, n, bad in ex.map(case, range(N)):
        tot += n; allbad += bad
print("commands", tot, "mismatches", len(allbad))
for c, o, n in allbad[:5]:
    print(c); print("ORIG", o); print("NEW ", n)

